-- ============================================================
-- Clothza — demo catalog seed
-- Run in Supabase → SQL Editor AFTER signing up once in the app
-- (stores.owner_id references the first profile created).
-- Safe to run twice: it exits if stores already exist.
-- ============================================================

do $$
declare
  owner uuid;
begin
  select id into owner from public.profiles order by joined_at asc limit 1;

  if owner is null then
    raise exception 'No profile found. Sign up in the app first, then run this again.';
  end if;

  if exists (select 1 from public.stores) then
    raise notice 'Catalog already seeded — nothing to do.';
    return;
  end if;

  insert into public.stores
    (owner_id, name, slug, description, logo, banner, location, instagram, whatsapp,
     theme, is_featured, is_sponsored, views, clicks, rating, review_count,
     subscription_tier, subscription_expires_at, created_at)
  values
    ((select id from profiles order by joined_at asc limit 1), 'Atelier Noir', 'atelier-noir', 'A temple of minimalist fashion from the boulevards of Paris. Atelier Noir believes that restraint is the ultimate luxury — every stitch purposeful, every silhouette architectural. We work exclusively with structured wool, merino, and double-faced cashmere sourced from heritage mills in Northern France. No prints, no excess, only form.', 'https://images.unsplash.com/photo-1558769132-cb1aea458c5e', 'https://images.unsplash.com/photo-1445205170230-053b83016050', 'Paris, France', '@ateliernoir', '+33123456789', 'minimalist', true, true, 48200, 3890, 4.8, 214, 'gold', '2027-01-01T00:00:00Z', '2025-01-15T08:00:00Z'),
    ((select id from profiles order by joined_at asc limit 1), 'Maison Blanc', 'maison-blanc', 'Born from the sun-drenched coast of the Amalfi, Maison Blanc is an ode to effortless living. Every garment breathes — sculpted from deadstock Belgian linen, organic cotton, and Tencel. Our design language is coastal minimalism meets Mediterranean warmth. Floaty silhouettes, natural dyes, and textures that soften with every wash.', 'https://images.unsplash.com/photo-1441986300917-64674bd600d8', 'https://images.unsplash.com/photo-1469334031218-e382a71b716b', 'Milano, Italy', '@maisonblanc', '+39123456789', 'boho', true, false, 31500, 2740, 4.6, 178, 'silver', '2026-09-01T00:00:00Z', '2025-03-10T08:00:00Z'),
    ((select id from profiles order by joined_at asc limit 1), 'Aura Studio', 'aura-studio', 'Aura Studio was born in the neon-lit backstreets of Shibuya. We are the pulse of Tokyo streetwear — gender-neutral silhouettes, tactical cargo constructions, and oversized proportions that command presence. Every drop is limited. Every piece is a statement. Aura exists for those who lead trends, not follow them.', 'https://images.unsplash.com/photo-1523381210434-271e8be1f52b', 'https://images.unsplash.com/photo-1558618666-fcd25c85cd64', 'Tokyo, Japan', '@aurastudio.tok', '+81312345678', 'streetwear', true, false, 27800, 2120, 4.7, 143, 'gold', '2026-12-01T00:00:00Z', '2025-02-20T08:00:00Z'),
    ((select id from profiles order by joined_at asc limit 1), 'Sol & Luna', 'sol-luna', 'From the workshops of Barcelona''s El Born district, Sol & Luna is an artisan leather house specialising in handmade sculptural accessories and luxury ready-to-wear. Each piece is constructed by a single artisan from start to finish. We use only vegetable-tanned, traceable hides. Beauty that deepens with age — the anti-disposable luxury.', 'https://images.unsplash.com/photo-1543163521-1bf539c55dd2', 'https://images.unsplash.com/photo-1490481651871-ab68de25d43d', 'Barcelona, Spain', '@solylunabcn', '+34912345678', 'luxury', false, true, 19300, 1650, 4.9, 97, 'bronze', '2026-07-01T00:00:00Z', '2025-05-08T08:00:00Z');

  insert into public.products
    (store_id, name, description, price, compare_at_price, category, tags, images,
     variants, is_best_seller, is_trending, is_sponsored, views, clicks, rating,
     review_count, created_at)
  values
    ((select id from stores where slug = 'atelier-noir'), 'Double-Faced Wool Overcoat', 'The cornerstone of Atelier Noir''s winter collection, this double-faced wool overcoat is cut from a single-layer of heritage Loro Piana fabric — dense enough to eliminate the need for lining. The silhouette is deliberately architectural: dropped shoulders, a cocoon back, and a clean notch lapel that closes with a single polished horn button. Worn open or closed, it transforms every outfit beneath it. A coat built not for a season, but for a decade. Available in Obsidian Black and Chalk White.', 48500, 58200, 'Men', array['wool','overcoat','minimalist','winter','luxury']::text[], array['https://images.unsplash.com/photo-1539533113208-f6df8cc8b543','https://images.unsplash.com/photo-1520975916090-3105956dac38','https://images.unsplash.com/photo-1516257984-b1b4d707412e']::text[], '[{"size":"XS","color":"Obsidian Black","stock":4},{"size":"S","color":"Obsidian Black","stock":8},{"size":"M","color":"Obsidian Black","stock":12},{"size":"L","color":"Obsidian Black","stock":6},{"size":"S","color":"Chalk White","stock":3},{"size":"M","color":"Chalk White","stock":5},{"size":"L","color":"Chalk White","stock":2}]'::jsonb, true, true, true, 8920, 743, 4.9, 67, '2025-10-01T08:00:00Z'),
    ((select id from stores where slug = 'atelier-noir'), 'Merino Turtleneck Ribbed Sweater', 'Spun from extra-fine 17.5-micron merino sourced directly from Australian Merino farms, this ribbed turtleneck represents Atelier Noir''s commitment to textile excellence. The tight-knit rib construction creates a self-supporting structure that holds its shape wash after wash. The extended turtleneck can be worn upright for a sculptural effect or folded back for a classical look. Anti-pilling treatment ensures pristine appearance through hundreds of wears. The ideal layer — worn alone or beneath the Wool Overcoat.', 18500, 22200, 'Men', array['merino','knitwear','turtleneck','minimalist']::text[], array['https://images.unsplash.com/photo-1576566588028-4147f3842f27','https://images.unsplash.com/photo-1614786269829-d24616faf56d']::text[], '[{"size":"XS","color":"Ivory","stock":6},{"size":"S","color":"Ivory","stock":14},{"size":"M","color":"Ivory","stock":18},{"size":"L","color":"Ivory","stock":10},{"size":"XL","color":"Ivory","stock":4},{"size":"S","color":"Charcoal Grey","stock":8},{"size":"M","color":"Charcoal Grey","stock":12},{"size":"L","color":"Charcoal Grey","stock":7}]'::jsonb, true, false, false, 6140, 512, 4.8, 88, '2025-10-15T08:00:00Z'),
    ((select id from stores where slug = 'atelier-noir'), 'Structured Wide-Leg Trousers', 'Atelier Noir''s signature wide-leg trouser is the product of eighteen months of pattern development. Cut from a mid-weight Japanese wool-polyester blend with just 2% elastane for comfort retention, the silhouette is a deliberate study in geometry. A high rise with a deep pleat at the front creates dramatic drape at the thigh, narrowing to a clean break above the shoe. Paired with the Merino Turtleneck, the ensemble becomes a complete editorial statement. Belt loops accommodate up to 4cm belts. Dry clean recommended.', 22000, 26400, 'Women', array['trousers','wide-leg','minimalist','tailored']::text[], array['https://images.unsplash.com/photo-1506629082955-511b1aa562c8']::text[], '[{"size":"24","color":"Black","stock":5},{"size":"26","color":"Black","stock":9},{"size":"28","color":"Black","stock":11},{"size":"30","color":"Black","stock":6},{"size":"32","color":"Black","stock":3},{"size":"26","color":"Ecru","stock":4},{"size":"28","color":"Ecru","stock":7}]'::jsonb, false, true, false, 4200, 380, 4.7, 41, '2025-11-01T08:00:00Z'),
    ((select id from stores where slug = 'maison-blanc'), 'Washed Linen Overshirt', 'Made from 100% enzyme-washed Belgian linen — a process that pre-softens the fibres to eliminate the stiff break-in period. The result is a garment that feels worn-in from the very first wear. Generous patch pockets, a relaxed boxy cut, and mother-of-pearl buttons characterise this cornerstone Maison Blanc piece. The overshirt transitions effortlessly from beach cover-up to urban weekend casual. Machine washable, it softens further with every cycle. Available in five natural, plant-derived dye colorways.', 12800, 15360, 'Women', array['linen','overshirt','boho','coastal','summer']::text[], array['https://images.unsplash.com/photo-1434389677669-e08b4cac3105','https://images.unsplash.com/photo-1515886657613-9f3515b0c78f','https://images.unsplash.com/photo-1496747611176-843222e1e57c']::text[], '[{"size":"XS","color":"Natural Sand","stock":7},{"size":"S","color":"Natural Sand","stock":15},{"size":"M","color":"Natural Sand","stock":20},{"size":"L","color":"Natural Sand","stock":8},{"size":"S","color":"Sage Green","stock":6},{"size":"M","color":"Sage Green","stock":10},{"size":"M","color":"Dusty Rose","stock":5}]'::jsonb, true, true, false, 7340, 621, 4.6, 93, '2025-08-01T08:00:00Z'),
    ((select id from stores where slug = 'maison-blanc'), 'Organic Cotton Wrap Dress', 'The quintessential Maison Blanc silhouette — a wrap construction in GOTS-certified organic cotton voile. The lightweight fabric catches every breeze, creating a natural, fluttering drape around the body. An adjustable self-tie wrap accommodates a range of body proportions, while the v-neckline creates an elegant, universally flattering frame. Hand-block printed in natural indigo using a traditional Rajasthani technique by our partner artisan cooperative. Each piece carries slight variations in print — a mark of authentic handwork rather than a flaw.', 15500, 18600, 'Women', array['organic','cotton','dress','boho','sustainable']::text[], array['https://images.unsplash.com/photo-1572804013427-4d7ca7268217','https://images.unsplash.com/photo-1539109136881-3be0616acf4b']::text[], '[{"size":"XS","color":"Indigo Print","stock":3},{"size":"S","color":"Indigo Print","stock":8},{"size":"M","color":"Indigo Print","stock":12},{"size":"L","color":"Indigo Print","stock":7},{"size":"XL","color":"Indigo Print","stock":2},{"size":"S","color":"Terra Block","stock":4},{"size":"M","color":"Terra Block","stock":6}]'::jsonb, false, true, false, 5100, 440, 4.5, 56, '2025-09-01T08:00:00Z'),
    ((select id from stores where slug = 'maison-blanc'), 'Linen Pleated Wide-Leg Pants', 'The companion bottom to the Washed Linen Overshirt, these wide-leg trousers share the same enzyme-washed Belgian linen for a unified, effortlessly coastal aesthetic. Deep knife pleats at the front create architectural movement as you walk, while an elasticated back waistband provides all-day comfort without visible hardware. The palazzo-width leg creates a dramatic silhouette that is equally at home on a Capri terrace or a Thamel rooftop. Our bestselling bottom — size-inclusive with an adjustable tie at the waist.', 13200, 15840, 'Women', array['linen','wide-leg','boho','resort','coastal']::text[], array['https://images.unsplash.com/photo-1509631179647-0177331693ae','https://images.unsplash.com/photo-1578587018452-892bacefd3f2']::text[], '[{"size":"XS","color":"Natural","stock":5},{"size":"S","color":"Natural","stock":12},{"size":"M","color":"Natural","stock":16},{"size":"L","color":"Natural","stock":9},{"size":"XL","color":"Natural","stock":4},{"size":"M","color":"Clay","stock":6},{"size":"L","color":"Clay","stock":4}]'::jsonb, true, false, false, 4890, 398, 4.7, 71, '2025-09-15T08:00:00Z'),
    ((select id from stores where slug = 'aura-studio'), 'Technical Cargo Wide-Leg Pants', 'Aura Studio''s flagship cargo — a technical masterpiece built for the streets of Shibuya. Cut from a 4-way stretch nylon-cotton ripstop blend, these wide-leg cargos feature eleven utility pockets (including two concealed zippered cargo pockets along the thigh), an articulated gusset crotch for unrestricted movement, and adjustable drawstring ankle cuffs. The dropped crotch construction and oversized silhouette are quintessentially Tokyo. Gender-neutral pattern, designed to fit a broad range of body types. Limited to 200 units per colorway — numbered inside the waistband.', 16800, 20160, 'Men', array['cargo','streetwear','technical','gender-neutral','limited']::text[], array['https://images.unsplash.com/photo-1578932750294-f5075e85f44a','https://images.unsplash.com/photo-1548126032-079a0fb0099d']::text[], '[{"size":"XS","color":"Olive Drab","stock":8},{"size":"S","color":"Olive Drab","stock":18},{"size":"M","color":"Olive Drab","stock":22},{"size":"L","color":"Olive Drab","stock":14},{"size":"XL","color":"Olive Drab","stock":6},{"size":"S","color":"Jet Black","stock":12},{"size":"M","color":"Jet Black","stock":16},{"size":"L","color":"Jet Black","stock":9}]'::jsonb, true, true, true, 9200, 812, 4.8, 104, '2025-07-01T08:00:00Z'),
    ((select id from stores where slug = 'aura-studio'), 'Oversized Graphic Hoodie', 'The Aura Studio Hoodie is a drop that sells out within hours of release. Constructed from a heavyweight 420gsm French terry cotton with a brushed interior for exceptional warmth, it wears like a second skin. The graphic — a generative art print created in collaboration with Tokyo digital artist Kenji Mori — is screen-printed using water-based inks on the back, running from hem to neckline. The silhouette is deliberately oversized: boxy body, dropped shoulders, and a wide kangaroo pocket. A drawcord-adjustable hood with large ribbed eyelets completes the construction. One size fits XS–XL.', 11500, 13800, 'Women', array['hoodie','oversized','streetwear','graphic','gender-neutral']::text[], array['https://images.unsplash.com/photo-1515886657613-9f3515b0c78f','https://images.unsplash.com/photo-1614786269829-d24616faf56d']::text[], '[{"size":"One Size","color":"Ash Grey","stock":30},{"size":"One Size","color":"Bone White","stock":15},{"size":"One Size","color":"Washed Navy","stock":20}]'::jsonb, true, true, false, 11200, 967, 4.7, 139, '2025-06-15T08:00:00Z'),
    ((select id from stores where slug = 'aura-studio'), 'Utility Tactical Vest', 'The Aura Studio Tactical Vest was born from a collaboration with a Tokyo workwear manufacturer. Six exterior pockets — two large cargo, two slim front, two internal zippered — provide functional storage in a garment that makes a bold visual statement. The body is constructed from a ripstop poly-nylon blend with a DWR (Durable Water Repellent) finish. Adjustable side buckle closures allow for a custom fit from XS to XL in a single size. Designed to layer over the Oversized Hoodie or wear alone over a longline base. A defining piece of the Aura aesthetic.', 9800, 11760, 'Accessories', array['vest','tactical','utility','streetwear','layering']::text[], array['https://images.unsplash.com/photo-1520975916090-3105956dac38','https://images.unsplash.com/photo-1620799140408-edc6dcb6d633']::text[], '[{"size":"One Size","color":"Ranger Green","stock":12},{"size":"One Size","color":"All Black","stock":18},{"size":"One Size","color":"Sand Tan","stock":8}]'::jsonb, false, true, false, 6380, 554, 4.6, 62, '2025-07-15T08:00:00Z'),
    ((select id from stores where slug = 'sol-luna'), 'Handcrafted Sculptural Tote', 'Each Sol & Luna Sculptural Tote is a unique object — handbuilt by a single artisan in Barcelona''s El Born workshop from a single piece of Hermès-grade vegetable-tanned calf leather. The construction method is traditional saddlery: hand-stitched with waxed linen thread at 12 stitches per inch, with a tension so precise it requires a single artisan''s entire day to complete one bag. The sculptural curved base — the signature Sol & Luna form — is achieved by wet-moulding and hand-shaping the leather over a wooden last. Zero hardware. Zero glue. Only leather and thread. Develops a rich, personal patina over years of use.', 85000, 102000, 'Accessories', array['leather','handmade','tote','luxury','artisan','sculptural']::text[], array['https://images.unsplash.com/photo-1548036328-c9fa89d128fa','https://images.unsplash.com/photo-1591561954557-26941169b49e']::text[], '[{"size":"One Size","color":"Natural Tan","stock":4},{"size":"One Size","color":"Espresso Brown","stock":3},{"size":"One Size","color":"Midnight Black","stock":2}]'::jsonb, false, true, true, 7800, 620, 5, 29, '2025-05-20T08:00:00Z'),
    ((select id from stores where slug = 'sol-luna'), 'Leather Ballet Flat — Archive Edition', 'Reissued from the Sol & Luna Archive (2019 debut season), the Ballet Flat remains the studio''s most beloved silhouette. Constructed entirely by hand from a single piece of butter-soft Nappa calf leather — no seams at the toe box — the shoe moulds precisely to the wearer''s foot within one week of daily wear. A hand-sewn leather sole with a hidden 5mm cork midsole provides surprising cushioning without compromise to the silhouette. The elasticated back gore is hidden beneath a leather wrap. Unlined for breathability. Re-soling service available at the Barcelona workshop.', 32000, 38400, 'Footwear', array['leather','flats','handmade','luxury','ballet']::text[], array['https://images.unsplash.com/photo-1543163521-1bf539c55dd2','https://images.unsplash.com/photo-1606107557195-0e29a4b5b4aa']::text[], '[{"size":"35","color":"Nude Nappa","stock":3},{"size":"36","color":"Nude Nappa","stock":5},{"size":"37","color":"Nude Nappa","stock":7},{"size":"38","color":"Nude Nappa","stock":6},{"size":"39","color":"Nude Nappa","stock":4},{"size":"40","color":"Nude Nappa","stock":2},{"size":"37","color":"Cherry Red","stock":3},{"size":"38","color":"Cherry Red","stock":4},{"size":"39","color":"Cherry Red","stock":2}]'::jsonb, true, false, false, 9200, 780, 4.9, 53, '2025-06-01T08:00:00Z'),
    ((select id from stores where slug = 'sol-luna'), 'Leather Slim Bifold Wallet', 'The Sol & Luna Slim Bifold is proof that the most considered object is often the smallest. Constructed from a single piece of vegetable-tanned Florentine calf leather from Conceria Walpier — the same tannery that supplies the world''s finest luxury houses — the wallet holds 6 cards, cash, and a folded receipt in a profile that sits barely 4mm thick. All edges are hand-bevelled and burnished with bone. The stitch — 8 saddle stitches in waxed linen — is functional, never decorative. This wallet will outlast its owner if cared for properly. A lifetime product, not a seasonal one.', 14500, 17400, 'Accessories', array['leather','wallet','handmade','luxury','minimalist']::text[], array['https://images.unsplash.com/photo-1627123424574-724758594e93','https://images.unsplash.com/photo-1553062407-98eeb64c6a62']::text[], '[{"size":"One Size","color":"Natural Tan","stock":12},{"size":"One Size","color":"Espresso Brown","stock":8},{"size":"One Size","color":"Midnight Black","stock":10}]'::jsonb, true, false, false, 5420, 466, 4.9, 44, '2025-07-01T08:00:00Z');

  insert into public.lookbooks
    (store_id, creator_name, name, description, cover_image, items, is_official,
     likes, views, created_at)
  values
    ((select id from stores where slug = 'aura-studio'), 'Aiden Chen', 'Tokyo After Dark', 'A nocturnal walk through Shimokitazawa — layered utilitarian silhouettes under the glow of vintage vinyl shop signs. This look is about texture tension: raw ripstop against brushed French terry, matte against reflective.', 'https://images.unsplash.com/photo-1558618666-fcd25c85cd64', '[{"productId":"prod-as-001","selectedSize":"M","selectedColor":"Jet Black"},{"productId":"prod-as-002","selectedSize":"One Size","selectedColor":"Ash Grey"},{"productId":"prod-as-003","selectedSize":"One Size","selectedColor":"All Black"}]'::jsonb, false, 2847, 19400, '2026-03-01T08:00:00Z'),
    ((select id from stores where slug = 'aura-studio'), 'Aiden Chen', 'Monochrome Ōmotesandō', 'An all-black uniform for the gallery walk. Every element is black, but never the same black — flat matte, brushed nylon, and washed cotton coexist in a symphony of darkness. Style is in the details.', 'https://images.unsplash.com/photo-1524504388940-b1c1722653e1', '[{"productId":"prod-as-003","selectedSize":"One Size","selectedColor":"All Black"},{"productId":"prod-an-001","selectedSize":"M","selectedColor":"Obsidian Black"}]'::jsonb, false, 2103, 14800, '2026-04-10T08:00:00Z'),
    ((select id from stores where slug = 'maison-blanc'), 'Sophia Laurent', 'Côte d''Azur Morning', 'Golden light, warm stone, and the faint smell of lavender. This lookbook captures the eternal French Riviera morning — effortless linen, bare skin, and a coffee held in both hands. Femininity without effort.', 'https://images.unsplash.com/photo-1469334031218-e382a71b716b', '[{"productId":"prod-mb-001","selectedSize":"S","selectedColor":"Sage Green"},{"productId":"prod-mb-003","selectedSize":"S","selectedColor":"Natural"}]'::jsonb, true, 1968, 12700, '2026-02-14T08:00:00Z'),
    ((select id from stores where slug = 'maison-blanc'), 'Sophia Laurent', 'The Art Basel Edit', 'For the opening night vernissage — comfortable enough for 6 hours on your feet, distinctive enough to be remembered. Organic cotton drape meets handmade leather sculpture in the ultimate gallery-to-dinner look.', 'https://images.unsplash.com/photo-1515886657613-9f3515b0c78f', '[{"productId":"prod-mb-002","selectedSize":"M","selectedColor":"Indigo Print"},{"productId":"prod-sl-001","selectedSize":"One Size","selectedColor":"Natural Tan"}]'::jsonb, false, 1642, 9300, '2026-05-01T08:00:00Z'),
    ((select id from stores where slug = 'sol-luna'), 'Mia Reyes', 'The Barcelona Edit', 'Born in the light of Gaudí — a study in material craft and Catalan soul. Vegetable-tanned leather as a lifestyle, not a luxury. The Ballet Flat and Sculptural Tote become armor for the modern woman who moves through the world with intention and craft.', 'https://images.unsplash.com/photo-1490481651871-ab68de25d43d', '[{"productId":"prod-sl-002","selectedSize":"38","selectedColor":"Nude Nappa"},{"productId":"prod-sl-001","selectedSize":"One Size","selectedColor":"Espresso Brown"},{"productId":"prod-an-003","selectedSize":"28","selectedColor":"Ecru"}]'::jsonb, false, 1284, 7900, '2026-01-20T08:00:00Z');

  raise notice 'Seeded % stores, % products, % lookbooks.',
    4, 12, 5;
end $$;
